import{_ as a,o as l,c as e,a3 as n}from"./chunks/framework.bvEHUNtb.js";const g=JSON.parse('{"title":"C-10 三才","description":"从原典、六爻结构与跨体系应用，理解天、地、人三才作为传统世界观的空间骨架。","frontmatter":{"title":"C-10 三才","description":"从原典、六爻结构与跨体系应用，理解天、地、人三才作为传统世界观的空间骨架。","category":"guide","outline":"deep","aliases":["三才","天地人三才","三才结构"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/three-talents.md","filePath":"topics/traditional-wisdom/common-knowledge/three-talents.md","lastUpdated":1786982540000}'),s={name:"topics/traditional-wisdom/common-knowledge/three-talents.md"};function o(i,t,r,p,d,u){return l(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="c-10-·-三才-天地人三位一体" tabindex="-1">C-10 · 三才：天地人三位一体 <a class="header-anchor" href="#c-10-·-三才-天地人三位一体" aria-label="Permalink to &quot;C-10 · 三才：天地人三位一体&quot;">​</a></h1><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 哲学概念组（C系列）<br><strong>版本：</strong> v1.0（2026年8月）<br><strong>前置篇目：</strong> 02·阴阳论 / 04·五行论 / 06·先天八卦 / 07·后天八卦<br><strong>后续篇目：</strong> C-11·精气神 / C-12·象数理</p><hr><h2 id="写在前面-为什么-三才-是所有体系的骨架" tabindex="-1">写在前面：为什么&quot;三才&quot;是所有体系的骨架？ <a class="header-anchor" href="#写在前面-为什么-三才-是所有体系的骨架" aria-label="Permalink to &quot;写在前面：为什么&quot;三才&quot;是所有体系的骨架？&quot;">​</a></h2><p>在中华传统文化里，有一个概念几乎无处不在，却常常被忽略——</p><p><strong>三才：天、地、人。</strong></p><p>它不是一个孤立的哲学命题，而是整个传统文化的<strong>空间骨架</strong>：</p><ul><li>六爻卦为什么是六画？——因为三才各两爻。</li><li>奇门遁甲为什么分天盘·地盘·人盘？——三才结构。</li><li>中医为什么讲&quot;天人合一&quot;？——人在天地之间，不可分割。</li><li>儒家为什么讲仁义？——仁是人道，对应天之阴阳、地之刚柔。</li></ul><p><strong>理解了三才，才能理解为什么所有体系都是&quot;三层结构&quot;。</strong></p><p>本篇目标：</p><ol><li>还原&quot;三才&quot;的原典出处与哲学逻辑。</li><li>厘清三才与六爻、八卦、中医、儒家的结构关联。</li><li>客观呈现&quot;天人合一&quot;与&quot;三才和谐&quot;的概念辨析。</li></ol><hr><h2 id="一、原典溯源-三才从哪里来" tabindex="-1">一、原典溯源：三才从哪里来？ <a class="header-anchor" href="#一、原典溯源-三才从哪里来" aria-label="Permalink to &quot;一、原典溯源：三才从哪里来？&quot;">​</a></h2><h3 id="_1-1-最早的完整表述——《周易·说卦传》" tabindex="-1">1.1 最早的完整表述——《周易·说卦传》 <a class="header-anchor" href="#_1-1-最早的完整表述——《周易·说卦传》" aria-label="Permalink to &quot;1.1 最早的完整表述——《周易·说卦传》&quot;">​</a></h3><blockquote><p>【原典】《周易·说卦传》第二章<br> 【原文】&quot;昔者圣人之作《易》也，将以顺性命之理，<br> 是以立天之道曰阴与阳，<br> 立地之道曰柔与刚，<br> 立人之道曰仁与义。<br> 兼三才而两之，故《易》六画而成卦。&quot;<br> 【版本】《周易正义》（唐·孔颖达疏，653年）</p></blockquote><p>这段话，是&quot;三才&quot;概念最完整、最权威的原典表述。</p><p>它说了三件事：</p><ol><li><strong>天有天道</strong>——阴与阳（气的变化）</li><li><strong>地有地道</strong>——柔与刚（形的变化）</li><li><strong>人有人道</strong>——仁与义（德的变化）</li></ol><p>然后说：<strong>&quot;兼三才而两之，故《易》六画而成卦。&quot;</strong></p><p>这一句，是六爻卦结构的哲学根据——<br> 三才，每才各两爻（初·二为地，三·四为人，五·上为天），<br> 合为六爻，一卦成立。</p><h3 id="_1-2-《系辞》的两处表述" tabindex="-1">1.2 《系辞》的两处表述 <a class="header-anchor" href="#_1-2-《系辞》的两处表述" aria-label="Permalink to &quot;1.2 《系辞》的两处表述&quot;">​</a></h3><blockquote><p>【原典一】《周易·系辞上传》<br> 【原文】&quot;六爻之动，三极之道也。&quot;<br> 说明：&quot;三极&quot;即三才——天极、地极、人极，各有其至理。</p></blockquote><blockquote><p>【原典二】《周易·系辞下传》第十章<br> 【原文】&quot;易之为书也，广大悉备，<br> 有天道焉，有人道焉，有地道焉，<br> 兼三才而两之，故六。<br> 六者，非他也，三才之道也。&quot;</p></blockquote><p>两处合看：</p><ul><li><strong>系辞上</strong>：三才是&quot;动&quot;的根据——六爻的每一次变动，都在演示天地人三道的互动。</li><li><strong>系辞下</strong>：三才是&quot;数&quot;的根据——六这个数字，不是随意的，是三才各两的结果。</li></ul><h3 id="_1-3-《三字经》的民间传承" tabindex="-1">1.3 《三字经》的民间传承 <a class="header-anchor" href="#_1-3-《三字经》的民间传承" aria-label="Permalink to &quot;1.3 《三字经》的民间传承&quot;">​</a></h3><blockquote><p>【原典】《三字经》（宋·王应麟，约1200年）<br> 【原文】&quot;三才者，天地人。三光者，日月星。&quot;</p></blockquote><p>这是三才概念从哲学经典走入民间蒙学的标志——<br> 每一个识字的中国孩子，都从这里开始知道&quot;天地人&quot;。<br> 但知道名字，和理解结构，是两件事。</p><hr><h2 id="二、哲学结构-三才不是-并列-是-层次" tabindex="-1">二、哲学结构：三才不是&quot;并列&quot;，是&quot;层次&quot; <a class="header-anchor" href="#二、哲学结构-三才不是-并列-是-层次" aria-label="Permalink to &quot;二、哲学结构：三才不是&quot;并列&quot;，是&quot;层次&quot;&quot;">​</a></h2><h3 id="_2-1-三才的基本结构" tabindex="-1">2.1 三才的基本结构 <a class="header-anchor" href="#_2-1-三才的基本结构" aria-label="Permalink to &quot;2.1 三才的基本结构&quot;">​</a></h3><p>很多人以为三才是&quot;天、地、人&quot;三个并列的东西。<br> 这是误解。</p><p>三才的真实结构，是<strong>层次关系</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天（上）——规律·气·阴阳·时间</span></span>
<span class="line"><span>    ↕</span></span>
<span class="line"><span>人（中）——感应·德·仁义·选择</span></span>
<span class="line"><span>    ↕</span></span>
<span class="line"><span>地（下）——承载·形·刚柔·空间</span></span></code></pre></div><p>人，不是天地之外的第三者，<br> 而是<strong>天地之间的中介</strong>——<br> 上承天道，下接地道，<br> 在天地之间，做出选择，体现德性。</p><p>这就是为什么《中庸》说：</p><blockquote><p>&quot;唯天下至诚，为能尽其性；<br> 能尽其性，则能尽人之性；<br> 能尽人之性，则能尽物之性；<br> 能尽物之性，则可以赞天地之化育；<br> 可以赞天地之化育，则可以与天地参矣。&quot;</p></blockquote><p><strong>&quot;与天地参&quot;——人参与天地的运化，不是旁观者，是参与者。</strong><br> 这是儒家三才观的核心：人不是被动的，是主动的中介。</p><h3 id="_2-2-三才与阴阳的关系" tabindex="-1">2.2 三才与阴阳的关系 <a class="header-anchor" href="#_2-2-三才与阴阳的关系" aria-label="Permalink to &quot;2.2 三才与阴阳的关系&quot;">​</a></h3><p>三才不是独立于阴阳之外的体系，而是阴阳的<strong>空间展开</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层次</th><th style="text-align:left;">对应</th><th style="text-align:left;">阴阳表现形式</th></tr></thead><tbody><tr><td style="text-align:left;">天道</td><td style="text-align:left;">时间·气候·运动</td><td style="text-align:left;">阴阳（寒暑·昼夜·消长）</td></tr><tr><td style="text-align:left;">地道</td><td style="text-align:left;">空间·地形·承载</td><td style="text-align:left;">刚柔（山泽·高下·动静）</td></tr><tr><td style="text-align:left;">人道</td><td style="text-align:left;">德性·关系·选择</td><td style="text-align:left;">仁义（仁柔·义刚·中和）</td></tr></tbody></table><p>阴阳是<strong>一维的</strong>（一分为二）；<br> 三才是<strong>三维的</strong>（天·地·人三个维度）。<br> 两者不矛盾——三才是阴阳在空间上的立体展开。</p><h3 id="_2-3-⚠️-概念辨析-三才和谐-vs-天人合一" tabindex="-1">2.3 ⚠️ 概念辨析：&quot;三才和谐&quot;vs&quot;天人合一&quot; <a class="header-anchor" href="#_2-3-⚠️-概念辨析-三才和谐-vs-天人合一" aria-label="Permalink to &quot;2.3 ⚠️ 概念辨析：&quot;三才和谐&quot;vs&quot;天人合一&quot;&quot;">​</a></h3><p>这两个概念，在现代语境中常常被混用，但有重要区别：</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">三才和谐</th><th style="text-align:left;">天人合一</th></tr></thead><tbody><tr><td style="text-align:left;">来源</td><td style="text-align:left;">《周易·说卦传》</td><td style="text-align:left;">庄子·道家传统</td></tr><tr><td style="text-align:left;">结构</td><td style="text-align:left;">天·地·人三者各有其道，和谐共处</td><td style="text-align:left;">人与天（自然）融为一体，消解边界</td></tr><tr><td style="text-align:left;">人的位置</td><td style="text-align:left;">独立的中介，有主动性</td><td style="text-align:left;">融入自然，消解个体</td></tr><tr><td style="text-align:left;">儒家倾向</td><td style="text-align:left;">更符合儒家本旨（人有主动德性）</td><td style="text-align:left;">更符合道家本旨（无为·自然）</td></tr><tr><td style="text-align:left;">现代误用</td><td style="text-align:left;">常被简化为&quot;环保·和谐&quot;口号</td><td style="text-align:left;">常被神秘化为&quot;合一体验&quot;</td></tr></tbody></table><p>⚠️ <strong>存疑标注：</strong><br> 学界对&quot;天人合一&quot;与&quot;三才和谐&quot;的关系，存在不同解读。<br> 部分学者（如哲学史研究）认为两者可以互补，<br> 部分学者（如儒学研究）认为&quot;三才和谐&quot;更准确地表达了儒家立场——<br> 因为儒家强调人的主动性与道德责任，而非消解于自然。<br> 本篇以&quot;三才和谐&quot;为主线，&quot;天人合一&quot;作为道家视角的补充呈现。</p><hr><h2 id="三、六爻结构-三才的数学落地" tabindex="-1">三、六爻结构：三才的数学落地 <a class="header-anchor" href="#三、六爻结构-三才的数学落地" aria-label="Permalink to &quot;三、六爻结构：三才的数学落地&quot;">​</a></h2><h3 id="_3-1-为什么卦是六画" tabindex="-1">3.1 为什么卦是六画？ <a class="header-anchor" href="#_3-1-为什么卦是六画" aria-label="Permalink to &quot;3.1 为什么卦是六画？&quot;">​</a></h3><p>这个问题，《说卦传》已经给出了答案：<br><strong>&quot;兼三才而两之，故《易》六画而成卦。&quot;</strong></p><p>具体对应：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上爻（第六爻）  ┐</span></span>
<span class="line"><span>五爻（第五爻）  ┘  → 天（天道·阴阳）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四爻（第四爻）  ┐</span></span>
<span class="line"><span>三爻（第三爻）  ┘  → 人（人道·仁义）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>二爻（第二爻）  ┐</span></span>
<span class="line"><span>初爻（第一爻）  ┘  → 地（地道·刚柔）</span></span></code></pre></div><p>朱熹《周易本义》注：</p><blockquote><p>&quot;初二为地，三四为人，五上为天。<br> 动，即变化也。极，至也。三极，天地人之至理。<br> 三才，各一太极也。&quot;</p></blockquote><p><strong>每一才，都是一个完整的太极。</strong><br> 天有天的阴阳，地有地的刚柔，人有人的仁义。<br> 六爻的变动，就是三个太极同时在运动。</p><h3 id="_3-2-读卦的三才视角" tabindex="-1">3.2 读卦的三才视角 <a class="header-anchor" href="#_3-2-读卦的三才视角" aria-label="Permalink to &quot;3.2 读卦的三才视角&quot;">​</a></h3><p>有了三才结构，读卦就有了空间感：</p><ul><li><strong>看天位（五·上爻）</strong>：这件事的大势、时机、外部环境如何？</li><li><strong>看人位（三·四爻）</strong>：当事人的处境、选择、行动空间如何？</li><li><strong>看地位（初·二爻）</strong>：事情的基础、根基、起点条件如何？</li></ul><p>这不是机械对应，而是一个<strong>立体读卦的框架</strong>——<br> 任何一件事，都有天时、地利、人和三个维度。</p><hr><h2 id="四、跨体系应用-三才结构无处不在" tabindex="-1">四、跨体系应用：三才结构无处不在 <a class="header-anchor" href="#四、跨体系应用-三才结构无处不在" aria-label="Permalink to &quot;四、跨体系应用：三才结构无处不在&quot;">​</a></h2><h3 id="_4-1-奇门遁甲-天盘·地盘·人盘" tabindex="-1">4.1 奇门遁甲：天盘·地盘·人盘 <a class="header-anchor" href="#_4-1-奇门遁甲-天盘·地盘·人盘" aria-label="Permalink to &quot;4.1 奇门遁甲：天盘·地盘·人盘&quot;">​</a></h3><p>奇门遁甲的盘面，本质上就是三才结构的空间展开：</p><table tabindex="0"><thead><tr><th style="text-align:left;">盘</th><th style="text-align:left;">对应三才</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">天盘</td><td style="text-align:left;">天</td><td style="text-align:left;">九星（天上的能量格局）</td></tr><tr><td style="text-align:left;">人盘</td><td style="text-align:left;">人</td><td style="text-align:left;">八门（人的行动方向）</td></tr><tr><td style="text-align:left;">地盘</td><td style="text-align:left;">地</td><td style="text-align:left;">八卦宫位（地理方位·空间）</td></tr></tbody></table><p>布局时，天盘·人盘·地盘叠加，<br> 看的就是天时·人事·地利三者的交汇点。</p><h3 id="_4-2-中医-天地人三才一体" tabindex="-1">4.2 中医：天地人三才一体 <a class="header-anchor" href="#_4-2-中医-天地人三才一体" aria-label="Permalink to &quot;4.2 中医：天地人三才一体&quot;">​</a></h3><blockquote><p>【原典】《黄帝内经·素问》<br> 【原文】&quot;天地合气，命之曰人。&quot;<br> 【版本】《黄帝内经素问》（唐·王冰注本）</p></blockquote><p>中医的&quot;三才一体&quot;，是医学模式的底层逻辑：</p><ul><li><strong>天</strong>：时令·气候·运气（五运六气）</li><li><strong>地</strong>：地域·水土·环境</li><li><strong>人</strong>：体质·脏腑·气血</li></ul><p>中医诊断，从不只看&quot;人&quot;——<br> 同一个病，在不同季节、不同地域、不同体质的人身上，<br> 治法可以完全不同。<br> 这不是&quot;玄学&quot;，是三才结构在医学上的严格应用。</p><h3 id="_4-3-儒家-仁义是人道的核心" tabindex="-1">4.3 儒家：仁义是人道的核心 <a class="header-anchor" href="#_4-3-儒家-仁义是人道的核心" aria-label="Permalink to &quot;4.3 儒家：仁义是人道的核心&quot;">​</a></h3><p>董仲舒在《春秋繁露》中，将三才结构与儒家伦理深度融合：</p><ul><li>天道：阴阳运行，有其规律，不可违逆</li><li>地道：刚柔承载，有其本分，各安其位</li><li>人道：仁义礼智，有其德性，主动参与</li></ul><p>儒家的核心主张，正是<strong>人在三才中的主动性</strong>——<br> 不是被动地顺应天地，而是主动地&quot;赞天地之化育&quot;，<br> 与天地并立为三，共同完成宇宙的运化。</p><h3 id="_4-4-风水·堪舆-三才的空间应用" tabindex="-1">4.4 风水·堪舆：三才的空间应用 <a class="header-anchor" href="#_4-4-风水·堪舆-三才的空间应用" aria-label="Permalink to &quot;4.4 风水·堪舆：三才的空间应用&quot;">​</a></h3><p>风水的核心逻辑，也是三才：</p><ul><li><strong>天时</strong>：何时动土、何时入宅（择日·节气）</li><li><strong>地利</strong>：山水格局、方位朝向（形势·理气）</li><li><strong>人和</strong>：居住者的命局与宅运的匹配（命宅相配）</li></ul><p>三者缺一，风水就是残缺的。</p><hr><h2 id="五、现代视角-三才的当代意义" tabindex="-1">五、现代视角：三才的当代意义 <a class="header-anchor" href="#五、现代视角-三才的当代意义" aria-label="Permalink to &quot;五、现代视角：三才的当代意义&quot;">​</a></h2><h3 id="_5-1-三才是一个-系统思维-框架" tabindex="-1">5.1 三才是一个&quot;系统思维&quot;框架 <a class="header-anchor" href="#_5-1-三才是一个-系统思维-框架" aria-label="Permalink to &quot;5.1 三才是一个&quot;系统思维&quot;框架&quot;">​</a></h3><p>用现代语言说，三才是一个<strong>三维系统分析框架</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任何问题，都有三个维度：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>天（宏观·趋势·时机）</span></span>
<span class="line"><span>——大环境怎样？时机对不对？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>地（客观·条件·资源）</span></span>
<span class="line"><span>——基础条件如何？资源在哪里？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>人（主观·选择·行动）</span></span>
<span class="line"><span>——我能做什么？我该怎么选？</span></span></code></pre></div><p>这不是玄学，这是<strong>古人总结的决策框架</strong>——<br> 任何一个维度缺失，判断都是片面的。</p><h3 id="_5-2-三才与现代生态观" tabindex="-1">5.2 三才与现代生态观 <a class="header-anchor" href="#_5-2-三才与现代生态观" aria-label="Permalink to &quot;5.2 三才与现代生态观&quot;">​</a></h3><p>三才结构，天然包含了现代生态学的核心洞察：</p><ul><li>人不是自然的主宰，而是天地之间的<strong>参与者</strong></li><li>人的行为，会影响天地的运化（气候·生态）</li><li>天地的变化，也会反过来影响人（灾害·疾病）</li></ul><p>这不是&quot;天人合一&quot;的神秘主义，<br> 而是一个严肃的<strong>系统反馈模型</strong>。</p><hr><h2 id="六、本章小结" tabindex="-1">六、本章小结 <a class="header-anchor" href="#六、本章小结" aria-label="Permalink to &quot;六、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三才体系 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 原典根据：</span></span>
<span class="line"><span>   《周易·说卦传》&quot;立天之道曰阴与阳，立地之道曰柔与刚，</span></span>
<span class="line"><span>   立人之道曰仁与义，兼三才而两之，故《易》六画而成卦。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 结构本质：</span></span>
<span class="line"><span>   三才不是并列，是层次——天在上，地在下，人居中介，</span></span>
<span class="line"><span>   上承天道，下接地道，主动参与天地运化。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 数学落地：</span></span>
<span class="line"><span>   六爻 = 三才 × 两爻，初二为地，三四为人，五上为天。</span></span>
<span class="line"><span>   六这个数字，不是随意的，是三才结构的必然结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 跨体系应用：</span></span>
<span class="line"><span>   奇门三盘·中医三才一体·儒家仁义人道·风水天时地利人和——</span></span>
<span class="line"><span>   三才结构，是所有传统体系的共用骨架。</span></span></code></pre></div><hr><h2 id="附-三才结构速查表" tabindex="-1">附：三才结构速查表 <a class="header-anchor" href="#附-三才结构速查表" aria-label="Permalink to &quot;附：三才结构速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">天</th><th style="text-align:left;">地</th><th style="text-align:left;">人</th></tr></thead><tbody><tr><td style="text-align:left;">《说卦传》定义</td><td style="text-align:left;">阴与阳</td><td style="text-align:left;">柔与刚</td><td style="text-align:left;">仁与义</td></tr><tr><td style="text-align:left;">六爻位置</td><td style="text-align:left;">五爻·上爻</td><td style="text-align:left;">初爻·二爻</td><td style="text-align:left;">三爻·四爻</td></tr><tr><td style="text-align:left;">奇门对应</td><td style="text-align:left;">天盘（九星）</td><td style="text-align:left;">地盘（八卦宫）</td><td style="text-align:left;">人盘（八门）</td></tr><tr><td style="text-align:left;">中医对应</td><td style="text-align:left;">时令·运气</td><td style="text-align:left;">地域·水土</td><td style="text-align:left;">体质·脏腑</td></tr><tr><td style="text-align:left;">儒家对应</td><td style="text-align:left;">天道·规律</td><td style="text-align:left;">地道·承载</td><td style="text-align:left;">人道·德性</td></tr><tr><td style="text-align:left;">风水对应</td><td style="text-align:left;">天时·择日</td><td style="text-align:left;">地利·山水</td><td style="text-align:left;">人和·命局</td></tr><tr><td style="text-align:left;">现代对应</td><td style="text-align:left;">宏观趋势·时机</td><td style="text-align:left;">客观条件·资源</td><td style="text-align:left;">主观选择·行动</td></tr></tbody></table><hr><p><strong>前置篇：</strong> C-09·九州<br><strong>后续篇：</strong> C-11·精气神（气的具体形态与三才的能量流动）</p>`,96)])])}const c=a(s,[["render",o]]);export{g as __pageData,c as default};
